#include <cstdarg>
#include <cstdio>
#include <cstring>
#include <string>

#include "testing/base/public/gunit.h"
#include "third_party/absl/cleanup/cleanup.h"
#include "third_party/stcorp_harp/google/util/scoped_harp.h"
#include "third_party/stcorp_harp/libharp/harp.h"

namespace stcorp_harp {
namespace {

std::string* g_print_buffer = nullptr;

int CapturePrint(const char* fmt, ...) {
  char buf[1024];
  va_list ap;
  va_start(ap, fmt);
  int n = std::vsnprintf(buf, sizeof(buf), fmt, ap);
  va_end(ap);
  if (g_print_buffer != nullptr && n >= 0) {
    g_print_buffer->append(buf);
  }
  return n;
}

TEST(HarpProductMetadataTest, NewInitializesDefaultsAndDeleteHandlesNull) {
  harp_product_metadata_delete(nullptr);

  harp_product_metadata* raw_meta = nullptr;
  ASSERT_EQ(HARP_SUCCESS, harp_product_metadata_new(&raw_meta));
  ScopedHarpProductMetadata meta(raw_meta);

  EXPECT_EQ(nullptr, meta->filename);
  EXPECT_EQ(nullptr, meta->format);
  EXPECT_EQ(nullptr, meta->source_product);
  EXPECT_EQ(nullptr, meta->history);
  EXPECT_DOUBLE_EQ(0.0, meta->datetime_start);
  EXPECT_DOUBLE_EQ(0.0, meta->datetime_stop);
  for (int i = 0; i < HARP_NUM_DIM_TYPES; ++i) {
    EXPECT_EQ(0L, meta->dimension[i]);
  }
}

TEST(HarpProductMetadataTest, DeleteFreesAllAllocatedStringFields) {
  harp_product_metadata* raw_meta = nullptr;
  ASSERT_EQ(HARP_SUCCESS, harp_product_metadata_new(&raw_meta));
  ScopedHarpProductMetadata meta(raw_meta);

  meta->filename = strdup("/dir/sample.nc");
  meta->format = strdup("HARP_NETCDF");
  meta->source_product = strdup("sample.nc");
  meta->history = strdup("generated by unit test");
  ASSERT_NE(nullptr, meta->filename);
  ASSERT_NE(nullptr, meta->format);
  ASSERT_NE(nullptr, meta->source_product);
  ASSERT_NE(nullptr, meta->history);
}

TEST(HarpProductMetadataTest, PrintFormatsUnquotedAndValidDatetimes) {
  harp_product_metadata* raw_meta = nullptr;
  ASSERT_EQ(HARP_SUCCESS, harp_product_metadata_new(&raw_meta));
  ScopedHarpProductMetadata meta(raw_meta);

  meta->filename = strdup("dir/product.nc");
  meta->source_product = strdup("product.nc");
  meta->datetime_start = 0.0;  // 2000-01-01T00:00:00
  meta->datetime_stop = 1.5;   // 2000-01-02T12:00:00
  meta->dimension[harp_dimension_time] = 10;
  meta->dimension[harp_dimension_latitude] = 20;
  meta->dimension[harp_dimension_longitude] = 30;
  meta->dimension[harp_dimension_vertical] = 40;
  meta->dimension[harp_dimension_spectral] = 50;

  std::string output;
  g_print_buffer = &output;
  auto reset_buf = absl::MakeCleanup([] { g_print_buffer = nullptr; });

  harp_product_metadata_print(meta.get(), CapturePrint);
  EXPECT_EQ(
      "dir/product.nc,20000101T000000,20000102T120000,10,20,30,40,50,"
      "product.nc\n",
      output);
}

TEST(HarpProductMetadataTest, PrintQuotesCommaNamesAndOmitsInfiniteDatetimes) {
  harp_product_metadata* raw_meta = nullptr;
  ASSERT_EQ(HARP_SUCCESS, harp_product_metadata_new(&raw_meta));
  ScopedHarpProductMetadata meta(raw_meta);

  meta->filename = strdup("dir/file,with,commas.nc");
  meta->source_product = strdup("source,with,comma");
  meta->datetime_start = harp_mininf();
  meta->datetime_stop = harp_plusinf();
  meta->dimension[harp_dimension_time] = 3;

  std::string output;
  g_print_buffer = &output;
  auto reset_buf = absl::MakeCleanup([] { g_print_buffer = nullptr; });

  harp_product_metadata_print(meta.get(), CapturePrint);
  EXPECT_EQ("\"dir/file,with,commas.nc\",,,3,0,0,0,0,\"source,with,comma\"\n",
            output);
}

}  // namespace
}  // namespace stcorp_harp
